import json, re

lines = open('ios_crash.ips').readlines()
raw = ''.join(lines[1:])
raw = re.sub(r'\"vmregioninfo\"', '\"vmregioninfo_lower\"', raw)
crash = json.loads(raw)
images = crash.get('usedImages', [])

dotnet_libs = ['libcoreclr', 'libmonosgen', 'libSystem.Native', 'libSystem.Globalization', 'libSystem.Security.Cryptography', 'libSystem.IO.Compression', 'libSystem.Net.Security']
dotnet_indices = set()
for i, img in enumerate(images):
    name = img.get('name', '')
    for lib in dotnet_libs:
        if lib in name:
            dotnet_indices.add(i)
    if 'SampleMAUI' in name:
        dotnet_indices.add(i)

# Find all threads with .NET frames
for t_idx, thread in enumerate(crash['threads']):
    frames = thread.get('frames', [])
    net_frames = []
    for j, f in enumerate(frames):
        idx = f['imageIndex']
        if idx in dotnet_indices:
            img = images[idx]
            addr = img['base'] + f['imageOffset']
            net_frames.append((j, idx, img, addr, f['imageOffset']))
    if net_frames:
        print(f'--- Thread {t_idx} ({\"FAULTING\" if t_idx == crash.get(\"faultingThread\") else \"\"}) ---')
        for j, idx, img, addr, offset in net_frames:
            print(f'  #{j}: {img[\"name\"]}  addr=0x{addr:x}  (base=0x{img[\"base\"]:x} + 0x{offset:x})  uuid={img[\"uuid\"]}')
        print()
" 2>&1", "description": "Find all .NET frames across threads"}
